/* From Uiverse.io by SelfMadeSystem - Tags: radio */
.__UIV_SCOPE__ .radio-input {
  --c: rgb(74, 156, 233);
}

.__UIV_SCOPE__ .radio-input label {
  position: relative;
  display: inline-block;
  border-radius: 99999px;
  appearance: unset;
  margin: 8px;
  width: 3em;
  height: 3em;
}

.__UIV_SCOPE__ .radio-input input {
  position: absolute;
  border-radius: 99999px;
  appearance: unset;
  inset: 0.75em;
  margin: 0;
  transition: background-color 0.5s;
}

.__UIV_SCOPE__ .radio-input input:checked {
  background-color: var(--c);
  filter: drop-shadow(0 0 10px var(--c));
}

.__UIV_SCOPE__ .radio-input svg {
  position: absolute;
  pointer-events: none;
  overflow: visible;
  filter: drop-shadow(0 0 4px var(--c));
}

.__UIV_SCOPE__ .radio-input svg .hi {
  width: 3em;
  height: 3em;
  rx: 1.5em;
  fill: transparent;
  stroke: var(--c);
  stroke-width: 0.25em;
  stroke-dasharray: 70 30;
  animation: strokeWee 32s linear infinite;
}

@keyframes strokeWee {
  0% {
    stroke-dashoffset: 0;
  }

  100% {
    stroke-dashoffset: 1000;
  }
}
